# File: res://scenes/card/card_scene.gd
extends Control

signal card_clicked(card_node: Control)

@onready var card_bg: Panel = $CardBg
@onready var card_art: TextureRect = get_node_or_null("CardArt")
@onready var top_rank_label: Label = $TopRankLabel
@onready var center_suit_label: Label = $CenterSuitLabel
@onready var click_button: Button = $ClickButton

@export var preview_rank_text: String = "7♥"
@export var preview_suit_text: String = "♥"
@export var preview_is_red: bool = true

var data: Variant = null
var is_selected: bool = false

func _ready() -> void:
	click_button.pressed.connect(_on_click_button_pressed)
	_refresh_visuals()

func setup(card_data: Variant) -> void:
	data = card_data
	if is_node_ready():
		_refresh_visuals()

func _refresh_visuals() -> void:
	if data == null:
		# Standalone preview mode (works immediately in Phase 1 before CardData exists!)
		top_rank_label.text = preview_rank_text
		center_suit_label.text = preview_suit_text
		var col: Color = Color("#FF5A67") if preview_is_red else Color("#ECF2F8")
		top_rank_label.modulate = col
		center_suit_label.modulate = col
		return

	# Full CardData mode (used from Phase 2 onward + downloaded sprite support!)
	var downloaded_tex: Texture2D = data.resolve_downloaded_texture() if data.has_method("resolve_downloaded_texture") else null
	if card_art != null and downloaded_tex != null:
		card_art.texture = downloaded_tex
		card_art.visible = true
		top_rank_label.visible = false
		center_suit_label.visible = false
	else:
		if card_art != null:
			card_art.visible = false
		top_rank_label.visible = true
		center_suit_label.visible = true
		top_rank_label.text = data.display_name
		center_suit_label.text = data.suit_symbol()
		var suit_color: Color = Color("#FF5A67") if data.is_red_suit() else Color("#ECF2F8")
		top_rank_label.modulate = suit_color
		center_suit_label.modulate = suit_color

func set_selected(selected: bool) -> void:
	is_selected = selected
	var lift: float = -14.0 if is_selected else 0.0
	card_bg.position.y = lift
	if card_art != null:
		card_art.position.y = lift
	top_rank_label.position.y = -8.0 if is_selected else 6.0
	center_suit_label.position.y = 24.0 if is_selected else 38.0

func _on_click_button_pressed() -> void:
	# If running CardScene standalone with F6, toggle lift directly so you can see it pop!
	if card_clicked.get_connections().is_empty():
		set_selected(not is_selected)
	card_clicked.emit(self)

