	status_label.text = "Karibu Kadi! 4-Player Table Ready"
	feedback_label.text = "Click any card in your hand below to lift and stage it!"
	_spawn_prototype_table()

func _spawn_prototype_table() -> void:
	# 1. Spawn the face-up starter card (6♥) in the center DiscardSlot:
	var starter: Control = CardScene.instantiate()
	discard_slot.add_child(starter)
	starter.preview_rank_text = "6♥"
	starter.preview_suit_text = "♥"
	starter.preview_is_red = true
	starter._refresh_visuals()

	# 2. Spawn 4 clickable cards fanned inside PlayerHandContainer:
	var demo_hand: Array = [
		{"rank": "7♥", "suit": "♥", "red": true},
		{"rank": "Q♥", "suit": "♥", "red": true},
		{"rank": "J♠", "suit": "♠", "red": false},
		{"rank": "A♦", "suit": "♦", "red": true}
	]
	for item in demo_hand:
		var card_node: Control = CardScene.instantiate()
		player_hand_container.add_child(card_node)
		card_node.preview_rank_text = item["rank"]
		card_node.preview_suit_text = item["suit"]
		card_node.preview_is_red = item["red"]
		card_node._refresh_visuals()

