extends Node2D

const CardScene: PackedScene = preload("res://scenes/card/card_scene.tscn")

@onready var discard_slot: Control = $DiscardSlot
@onready var player_hand_container: HBoxContainer = $PlayerHandContainer
@onready var status_label: Label = $HUD/StatusLabel
@onready var feedback_label: Label = $HUD/FeedbackLabel
@onready var play_button: Button = $HUD/PlaySelectedButton
@onready var draw_button: Button = $HUD/DrawButton

var staged_nodes: Array[Control] = []

func _ready() -> void:
	play_button.pressed.connect(_on_play_selected_pressed)
	draw_button.pressed.connect(_on_draw_pressed)
	_spawn_prototype_table()

func _spawn_prototype_table() -> void:
	_set_discard_card("6♥", "♥", true)
	for item in [
		{"rank": "7♥", "suit": "♥", "red": true},
		{"rank": "Q♥", "suit": "♥", "red": true},
		{"rank": "J♠", "suit": "♠", "red": false},
		{"rank": "A♦", "suit": "♦", "red": true}
	]:
		_add_hand_card(item["rank"], item["suit"], item["red"])

func _add_hand_card(rank_txt: String, suit_txt: String, is_red: bool) -> void:
	var card_node: Control = CardScene.instantiate()
	player_hand_container.add_child(card_node)
	card_node.preview_rank_text = rank_txt
	card_node.preview_suit_text = suit_txt
	card_node.preview_is_red = is_red
	card_node._refresh_visuals()
	card_node.card_clicked.connect(_on_hand_card_clicked)

func _set_discard_card(rank_txt: String, suit_txt: String, is_red: bool) -> void:
	for child in discard_slot.get_children():
		child.queue_free()
	var top_node: Control = CardScene.instantiate()
	discard_slot.add_child(top_node)
	top_node.preview_rank_text = rank_txt
	top_node.preview_suit_text = suit_txt
	top_node.preview_is_red = is_red
	top_node._refresh_visuals()

func _on_hand_card_clicked(card_node: Control) -> void:
	if card_node in staged_nodes:
		staged_nodes.erase(card_node)
		card_node.set_selected(false)
	else:
		staged_nodes.append(card_node)
		card_node.set_selected(true)
	play_button.text = "Play Selected (%d)" % staged_nodes.size()

func _on_play_selected_pressed() -> void:
	if staged_nodes.is_empty():
		return
	var last_card: Control = staged_nodes.back()
	_set_discard_card(last_card.preview_rank_text, last_card.preview_suit_text, last_card.preview_is_red)
	var played_names: Array[String] = []
	for c in staged_nodes:
		played_names.append(c.preview_rank_text)
		c.queue_free()
	staged_nodes.clear()
	play_button.text = "Play Selected (0)"
	feedback_label.text = "Played to Discard Pile: %s!" % ", ".join(played_names)

func _on_draw_pressed() -> void:
	var pool: Array = [
		{"rank": "2♠", "suit": "♠", "red": false},
		{"rank": "10♦", "suit": "♦", "red": true},
		{"rank": "K♣", "suit": "♣", "red": false},
		{"rank": "8♥", "suit": "♥", "red": true}
	]
	var pick: Dictionary = pool.pick_random()
	_add_hand_card(pick["rank"], pick["suit"], pick["red"])
	feedback_label.text = "Drew %s into your hand!" % pick["rank"]

